import {addDays,demoProjects,demoMilestones,demoTasks,demoInitiatives,demoActivity} from './data.js';

/* Prototype only: no authentication, backend, or access control is implemented.
   Every record is synthetic. Never load real project data into public Pages. */
const STORE='mp-projects-prototype-v1';
const seed={projects:demoProjects,milestones:demoMilestones,tasks:demoTasks,initiatives:demoInitiatives,activity:demoActivity,reports:[]};
function load(){try{const v=JSON.parse(localStorage.getItem(STORE));if(v&&Array.isArray(v.projects)&&Array.isArray(v.tasks))return v;}catch{}return structuredClone(seed)}
let db=load();
const state={view:'overview',role:'portfolio',selectedProject:null,projectTab:'summary',modal:null,search:'',filter:'all',type:'all',calendarOffset:0,reportProject:db.projects[0]?.id,reportType:'portfolio',notesProject:db.projects[0]?.id,showNotifications:false,mobileMenu:false,toast:null,selectedInitiative:null};
const save=()=>{try{localStorage.setItem(STORE,JSON.stringify(db))}catch(e){console.warn('Storage unavailable: changes are temporary',e)}};
const h=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n/1000000)+' млн ₽';
const shortMoney=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n)+' ₽';
const daydiff=d=>Math.round((new Date(d+'T12:00:00')-new Date(new Date().toDateString()+' 12:00:00'))/86400000);
const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'2-digit',month:'short',year:'numeric'}):'—';
const dayMonth=d=>{const t=new Date(d+'T12:00:00');return `<div class="date-box"><b>${t.getDate()}</b><small>${t.toLocaleDateString('ru-RU',{month:'short'})}</small></div>`};
const pl=(count,one,many,few)=>`${count} ${count%10===1&&count%100!==11?one:(count%10>=2&&count%10<=4&&(count%100<12||count%100>14))?few:many}`;
const project=id=>db.projects.find(p=>p.id===id);
const pm=id=>db.milestones.filter(m=>m.projectId===id);
const pt=id=>db.tasks.filter(t=>t.projectId===id);
const active=m=>m.state!=='accepted';
function health(p){
 const overdue=pm(p.id).filter(m=>active(m)).map(m=>-daydiff(m.date)).filter(x=>x>0);
 const soon=pm(p.id).some(m=>active(m)&&daydiff(m.date)>=0&&daydiff(m.date)<=7);
 if(overdue.some(x=>x>14)||p.spent>p.approved*1.1||p.risks?.some(r=>r.level==='Критический'))return 'red';
 if(overdue.length||soon||daydiff(p.updated)<-31||p.spent>p.approved)return 'yellow';
 return 'green';
}
function reason(p){let over=pm(p.id).filter(m=>active(m)&&daydiff(m.date)<0).sort((a,b)=>daydiff(a.date)-daydiff(b.date));
 if(over.length)return `Просрочена КТ на ${-daydiff(over[0].date)} дн.`;
 if(daydiff(p.updated)<-31)return 'Не обновлён месячный статус';
 if(p.spent>p.approved)return 'Отклонение по бюджету';
 let upcoming=pm(p.id).filter(m=>active(m)&&daydiff(m.date)>=0).sort((a,b)=>daydiff(a.date)-daydiff(b.date));
 if(upcoming.length&&daydiff(upcoming[0].date)<=7)return `КТ через ${daydiff(upcoming[0].date)} дн.`;
 return 'Без критических отклонений';
}
const labelHealth={green:'В графике',yellow:'Внимание',red:'Отклонение'};
const badge=(s,text=labelHealth[s])=>`<span class="pill ${s}"><span class="signal"></span>${h(text)}</span>`;
const statuses=['К выполнению','В работе','На проверке','Выполнена','Заблокирована'];
const stages=['Черновик','На рассмотрении','Предложение','Предварительно одобрено','Утверждение','Инициация'];
const nav=[['overview','layout-dashboard','Обзор портфеля'],['projects','folders','Все проекты'],['tasks','list-todo','Задачи'],['milestones','flag-triangle-right','Контрольные точки'],['calendar','calendar-days','Календарь портфеля'],['initiatives','git-pull-request','Инициативы'],['reports','file-chart-column','Отчётность'],['activity','message-square-text','Лента событий'],['settings','settings','Настройки']];
const paths={
 'layout-dashboard':'<rect x="3" y="3" width="7" height="9" rx="1"/><rect x="14" y="3" width="7" height="5" rx="1"/><rect x="14" y="12" width="7" height="9" rx="1"/><rect x="3" y="16" width="7" height="5" rx="1"/>',
 folders:'<path d="M2 8V5a2 2 0 0 1 2-2h5l2 2h5a2 2 0 0 1 2 2v1"/><path d="M4 9h16a2 2 0 0 1 2 2l-2 8a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2L2 11a2 2 0 0 1 2-2Z"/>',
 'list-todo':'<rect x="3" y="4" width="7" height="7" rx="1"/><path d="m5 7 2 2 3-4M14 8h7M4 17l2 2 4-4M14 18h7"/>',
 'flag-triangle-right':'<path d="M4 22V4M4 4h15l-4 6 4 6H4"/>',
 'calendar-days':'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18M8 14h1M12 14h1M16 14h1M8 18h1M12 18h1"/>',
 'git-pull-request':'<circle cx="6" cy="3" r="2"/><path d="M6 5v12"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="6" r="2"/><path d="M18 8v5a5 5 0 0 1-5 5h-2"/>',
 'file-chart-column':'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 18v-4M12 18v-7M16 18v-3"/>',
 'message-square-text':'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z"/><path d="M8 10h8M8 14h5"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.7 2.7-.1-.1a1.7 1.7 0 0 0-1.9-.3l-.3.1V22H9.2v-2.6L9 19.3a1.7 1.7 0 0 0-1.9.3l-.1.1-2.7-2.7.1-.1a1.7 1.7 0 0 0 .3-1.9l-.1-.2H2v-5.6h2.6l.1-.2a1.7 1.7 0 0 0-.3-1.9l-.1-.1L7 4.3l.1.1a1.7 1.7 0 0 0 1.9.3l.2-.1V2h5.6v2.6l.2.1a1.7 1.7 0 0 0 1.9-.3l.1-.1 2.7 2.7-.1.1a1.7 1.7 0 0 0-.3 1.9l.1.2H22v5.6h-2.6Z"/>',
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',chevron:'<path d="m9 18 6-6-6-6"/>',down:'<path d="m6 9 6 6 6-6"/>',
 alert:'<path d="M10.3 3.9 2 18.1A2 2 0 0 0 3.7 21h16.6a2 2 0 0 0 1.7-2.9L13.7 3.9a2 2 0 0 0-3.4 0ZM12 9v4M12 17h.01"/>',
 check:'<path d="m4 12 5 5L20 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',download:'<path d="M12 3v12m0 0 4-4m-4 4-4-4M4 17v3h16v-3"/>',
 filter:'<path d="M4 5h16M7 12h10M10 19h4"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',
 x:'<path d="M18 6 6 18M6 6l12 12"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',
 refresh:'<path d="M20 7v5h-5M4 17v-5h5M5.8 9A8 8 0 0 1 19 7l1 5M4 12l1 5a8 8 0 0 0 13.2-2"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6"/>',
 zap:'<path d="m13 2-9 12h7l-1 8 10-12h-7l0-8Z"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>'};
function icon(name,size=17){return `<svg class="icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.file}</svg>`}
function button(label,act,kind='',ic=''){return `<button type="button" class="button ${kind}" data-action="${act}">${ic?icon(ic):''}${label}</button>`}
function header(title,subtitle,eyebrow='ПОРТФЕЛЬ СЦ-2',actions=''){return `<div class="page-heading"><div><div class="eyebrow"><i class="red-dot"></i>${h(eyebrow)}</div><h1>${h(title)}</h1><div class="subheading">${subtitle}</div></div><div class="heading-buttons">${actions}</div></div>`}
function addActivity(projectId,name,text,kind='comment'){db.activity.unshift({id:'A-'+Date.now(),projectId,date:addDays(0),name,text,kind});save()}
function notify(msg,warn=false){state.toast={msg,warn};render();setTimeout(()=>{if(state.toast?.msg===msg){state.toast=null;render()}},3200)}
function navTo(view){state.view=view;state.selectedProject=null;state.mobileMenu=false;state.search='';state.filter='all';render();window.scrollTo({top:0,behavior:'instant'})}
function sidebar(){return `<aside class="sidebar ${state.mobileMenu?'mobile-open':''}"><div class="brand"><div class="brand-symbol">МП</div><div><strong>МП Проекты</strong><small>ПРОЕКТНЫЙ ОФИС</small></div></div><div class="sidebar-caption">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav class="sidebar-menu">${nav.map(n=>`<button class="nav-link ${state.view===n[0]?'active':''}" data-nav="${n[0]}">${icon(n[1])}<span>${n[2]}</span>${n[0]==='milestones'&&db.milestones.some(m=>m.state==='submitted')?`<span class="nav-count">${db.milestones.filter(m=>m.state==='submitted').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-footer"><div class="demo-stamp">${icon('alert',15)}<span>Демо-режим: только вымышленные данные. Авторизация будет подключена на сервере.</span></div><div class="footer-user"><div class="avatar red">МП</div><div><strong>Пилот СЦ-2</strong><small>Универсальная архитектура</small></div></div></div></aside>`}
function frame(){return `<div class="app">${sidebar()}<main class="main"><header class="topbar"><button class="circle-btn mobile-menu" data-action="mobilemenu" aria-label="Открыть меню">${icon('menu')}</button><div class="breadcrumb">МП Проекты ${icon('chevron',12)} <span>Стратегическая цель №2</span> ${icon('chevron',12)} <strong>${h(nav.find(n=>n[0]===state.view)?.[2]||'Обзор')}</strong></div><div class="topbar-right"><select class="role-select" id="demoRole" aria-label="Роль в демонстрации"><option value="portfolio" ${state.role==='portfolio'?'selected':''}>Руководитель портфеля</option><option value="manager" ${state.role==='manager'?'selected':''}>Руководитель проекта</option><option value="member" ${state.role==='member'?'selected':''}>Участник проекта</option><option value="rector" ${state.role==='rector'?'selected':''}>Ректор (просмотр)</option></select><div class="header-divider"></div><button class="circle-btn" data-action="notifications" title="Уведомления">${icon('bell')}${notices().length?'<span class="dot"></span>':''}</button><div class="avatar red">${state.role==='rector'?'РК':state.role==='manager'?'РП':state.role==='member'?'УЧ':'ПО'}</div></div>${state.showNotifications?notificationsPopup():''}</header><div class="content" id="content">${state.role==='rector'&&state.view!=='overview'?`<div class="banner">${icon('eye')} В демонстрационной роли ректора доступна только аналитика. Выберите «Обзор портфеля».</div>`:''}${views[state.view]?.()||overview()}</div></main></div>${state.modal?renderModal():''}<div class="toasts">${state.toast?`<div class="toast ${state.toast.warn?'warn':''}">${h(state.toast.msg)}</div>`:''}</div>`}
const notices=()=>db.milestones.filter(m=>m.state==='submitted'||(active(m)&&daydiff(m.date)<0)).sort((a,b)=>daydiff(a.date)-daydiff(b.date));
function notificationsPopup(){return `<div class="notification-dropdown"><div class="title-row"><b style="font-size:14px">Уведомления</b><button class="close" data-action="notifications">${icon('x')}</button></div><p class="subheading">События рассчитаны из демонстрационных контрольных точек.</p>${notices().slice(0,5).map(m=>`<div class="notice"><span class="notice-dot ${m.state==='submitted'?'blue':'red'}">${icon('bell')}</span><div><b>${h(m.name)}</b><small>${h(project(m.projectId)?.short)}</small><em>${m.state==='submitted'?'Ожидает вашей приёмки':`Просрочено на ${-daydiff(m.date)} дн.`}</em></div></div>`).join('')||'<div class="empty">Новых уведомлений нет</div>'}</div>`}
function stats(){const c={green:0,yellow:0,red:0};db.projects.forEach(p=>c[health(p)]++);const budget=db.projects.reduce((s,p)=>s+p.approved,0);const due=db.milestones.filter(m=>active(m)&&daydiff(m.date)>=0&&daydiff(m.date)<=14).length;return [
 ['Проектов',db.projects.length,'Всего в портфеле','folders',''],['В графике',c.green,'Без отклонений','check','green'],['Внимание',c.yellow,'Требуют контроля','clock','yellow'],['Отклонения',c.red,'Требуют решения','alert','red'],['Ближайшие КТ',due,'В пределах 14 дней','flag-triangle-right',''],['Бюджет',money(budget),'План на портфель','briefcase','']].map(x=>`<div class="stat ${x[4]}"><div class="stat-head"><span>${x[0]}</span><span class="stat-icon">${icon(x[3])}</span></div><div class="stat-value mono">${x[1]}</div><div class="stat-note">${x[2]}</div></div>`).join('')}
function projectRow(p){return `<tr><td><button class="text-link titlecell" data-project="${h(p.id)}">${h(p.short)}<small>${h(p.id)} · ${h(p.unit)}</small></button></td><td>${h(p.manager)}</td><td>${badge(health(p))}</td><td><div class="progress-cell"><div class="progress-track" style="width:58px"><div class="progress-fill" style="width:${Math.min(100,p.progress)}%"></div></div><small>${p.progress}%</small></div></td><td class="nowrap">${pm(p.id).filter(active).sort((a,b)=>daydiff(a.date)-daydiff(b.date)).map(m=>fmt(m.date))[0]||'—'}</td><td>${h(reason(p))}</td><td><button class="circle-btn" title="Карточка проекта" data-project="${h(p.id)}">${icon('chevron',15)}</button></td></tr>`}
function noticesPanel(){const sorted=[...db.projects].sort((a,b)=>({red:0,yellow:1,green:2}[health(a)]-({red:0,yellow:1,green:2}[health(b)]))).filter(p=>health(p)!=='green').slice(0,5);return `<section class="panel"><div class="panel-header"><div><div class="panel-title">Требует внимания</div><div class="panel-subtitle">Автоматический контроль отклонений</div></div><span class="pill red">${sorted.length} сигналов</span></div><div class="notice-list">${sorted.map(p=>`<div class="notice"><div class="notice-dot ${health(p)}">${icon('alert')}</div><div><b><button class="text-link" data-project="${p.id}">${h(p.short)}</button></b><small>${h(p.manager)}</small><em>${h(reason(p))}</em></div></div>`).join('')||'<div class="empty">Нет отклонений</div>'}</div><div class="panel-footer"><span>Просрочка > 14 дней = красный</span><button class="quiet-link" data-nav="projects">Все проекты ${icon('arrow',13)}</button></div></section>`}
function milestoneRows(ms){return ms.map(m=>{const delta=daydiff(m.date),st=m.state==='accepted'?'green':m.state==='submitted'?'blue':delta<0?'red':delta<=7?'yellow':'neutral',txt=m.state==='accepted'?'Принята':m.state==='submitted'?'На приёмке':delta<0?`Просрочена ${-delta} дн.`:delta<=7?'Скоро срок':'По плану';return `<tr><td><button class="text-link titlecell" data-project="${h(m.projectId)}">${h(m.name)}<small>${h(m.id)} · ${h(project(m.projectId)?.short)}</small></button></td><td class="nowrap">${fmt(m.date)}</td><td>${badge(st,txt)}</td><td>${h(m.owner)}</td><td><button class="button mini" data-milestone="${h(m.id)}">Подробнее</button></td></tr>`}).join('')}
function historyList(events){return events.map(e=>`<div class="history-item ${e.kind==='alert'?'alert':''}"><b>${h(e.name)}</b><p>${h(e.text)}</p><small>${fmt(e.date)} · ${h(project(e.projectId)?.short||'Портфель')}</small></div>`).join('')}
function overview(){let upcoming=db.milestones.filter(m=>active(m)).sort((a,b)=>daydiff(a.date)-daydiff(b.date)).slice(0,6);let lead=`${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})} · Пилот на СЦ-2 · ${db.projects.length} демонстрационных проектов`;
return header('Портфель образовательных проектов',lead,'СТРАТЕГИЧЕСКАЯ ЦЕЛЬ №2',button('Добавить проект','new-project','primary','plus')+button('Отчёт ректору','go-reports','','file-chart-column'))+
`<div class="stats">${stats()}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><div class="panel-title">Состояние проектов</div><div class="panel-subtitle">Сводка по портфелю и управленческим сигналам</div></div><button class="quiet-link" data-nav="projects">Все проекты ${icon('arrow',13)}</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Проект</th><th>Руководитель</th><th>Статус</th><th>Готовность</th><th>Ближайшая КТ</th><th>Сигнал</th><th></th></tr></thead><tbody>${[...db.projects].sort((a,b)=>({red:0,yellow:1,green:2}[health(a)]-({red:0,yellow:1,green:2}[health(b)]))).map(projectRow).join('')}</tbody></table></div><div class="panel-footer"><span>Нажмите на проект для перехода к подробностям</span><button class="quiet-link" data-nav="projects">Показать реестр ${icon('arrow',13)}</button></div></section>${noticesPanel()}</div><div class="bottom-grid"><section class="panel"><div class="panel-header"><div><div class="panel-title">Ближайшие контрольные точки</div><div class="panel-subtitle">Плановые сроки и приёмка результатов</div></div><button class="quiet-link" data-nav="calendar">Открыть календарь ${icon('arrow',13)}</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Контрольная точка</th><th>Срок</th><th>Состояние</th><th>Ответственный</th><th></th></tr></thead><tbody>${milestoneRows(upcoming)}</tbody></table></div></section><section class="panel"><div class="panel-header"><div><div class="panel-title">Лента изменений</div><div class="panel-subtitle">События, решения и подтверждения</div></div><button class="quiet-link" data-nav="activity">Вся история ${icon('arrow',13)}</button></div><div style="padding:0 22px 15px">${historyList(db.activity.slice(0,5))}</div></section></div>`}
function projects(){let items=db.projects.filter(p=>(state.filter==='all'||health(p)===state.filter)&&(state.type==='all'||p.type===state.type)&&`${p.name} ${p.id} ${p.manager} ${p.unit}`.toLowerCase().includes(state.search.toLowerCase()));return header('Реестр проектов',`Найдено ${items.length} из ${db.projects.length}. Фильтрация по типу, руководителю и состоянию.`,'ПРОЕКТЫ',button('Новый проект','new-project','primary','plus'))+`<section class="panel"><div class="panel-header"><div><div class="panel-title">Все проекты портфеля</div><div class="panel-subtitle">Стратегические, операционные, новые и продолжающиеся</div></div></div><div class="filters"><input id="projectsSearch" class="form-control compact search" placeholder="Поиск по проекту, РП, подразделению…" value="${h(state.search)}"/><select class="form-control compact" id="projectsStatus"><option value="all">Все состояния</option><option value="green" ${state.filter==='green'?'selected':''}>В графике</option><option value="yellow" ${state.filter==='yellow'?'selected':''}>Внимание</option><option value="red" ${state.filter==='red'?'selected':''}>Отклонение</option></select><select class="form-control compact" id="projectsType"><option value="all">Все типы</option><option value="Стратегический" ${state.type==='Стратегический'?'selected':''}>Стратегические</option><option value="Операционный" ${state.type==='Операционный'?'selected':''}>Операционные</option></select>${button('Сбросить','clear-filters','mini','refresh')}</div><div class="table-scroll"><table class="data-table"><thead><tr><th>Проект</th><th>Руководитель</th><th>Статус</th><th>Готовность</th><th>Ближайшая КТ</th><th>Причина</th><th></th></tr></thead><tbody>${items.map(projectRow).join('')||'<tr><td colspan="7" class="empty">Проекты не найдены</td></tr>'}</tbody></table></div></section>`}
function tasks(){const opts=db.projects.map(p=>`<option value="${h(p.id)}" ${state.reportProject===p.id?'selected':''}>${h(p.short)}</option>`).join('');const ts=state.reportProject==='all'?db.tasks:db.tasks.filter(t=>t.projectId===state.reportProject);return header('Задачи команды','Перетаскивайте карточки между колонками или меняйте статус в списке. Изменения сохраняются в браузере.','TASK TRACKER',button('Новая задача','new-task','primary','plus'))+`<div class="banner">${icon('zap')} В демонстрационном режиме задачи могут менять статус без серверной проверки ролей. В рабочей версии права будут контролироваться на сервере.</div><div class="panel" style="padding:17px 20px;margin-bottom:18px"><div class="title-row"><b style="font-size:12px">Проект</b><select id="tasksProject" class="form-control compact" style="max-width:390px"><option value="all" ${state.reportProject==='all'?'selected':''}>Все проекты портфеля</option>${opts}</select></div></div><div class="kanban">${statuses.map(s=>`<div class="kanban-col" data-dropstatus="${h(s)}"><div class="kanban-head">${h(s)}<span>${ts.filter(t=>t.status===s).length}</span></div>${ts.filter(t=>t.status===s).map(t=>`<div class="task-card" draggable="true" data-drag="${h(t.id)}"><b>${h(t.name)}</b><small>${h(project(t.projectId)?.short)} · ${h(t.id)}</small><small>${h(t.assignee)} · ${fmt(t.due)}</small><div class="task-card-bottom"><span class="tag">${h(t.priority)}</span><select data-taskstatus="${h(t.id)}" aria-label="Изменить статус задачи">${statuses.map(z=>`<option value="${h(z)}" ${s===z?'selected':''}>${h(z)}</option>`).join('')}</select></div></div>`).join('')}</div>`).join('')}</div>`}
function milestones(){const ordered=[...db.milestones].sort((a,b)=>daydiff(a.date)-daydiff(b.date));return header('Контрольные точки','Контроль результатов проекта, подтверждение фактов и приёмка руководителем портфеля.','КОНТРОЛЬ',button('Добавить КТ','new-milestone','primary','plus'))+`<div class="compact-stat-grid"><div class="stat green"><div class="stat-head">Приняты</div><div class="stat-value">${db.milestones.filter(m=>m.state==='accepted').length}</div></div><div class="stat yellow"><div class="stat-head">Ожидают приёмки</div><div class="stat-value">${db.milestones.filter(m=>m.state==='submitted').length}</div></div><div class="stat red"><div class="stat-head">Просрочены</div><div class="stat-value">${db.milestones.filter(m=>active(m)&&daydiff(m.date)<0).length}</div></div></div><section class="panel"><div class="panel-header"><div><div class="panel-title">Реестр контрольных точек</div><div class="panel-subtitle">Уровень КТ-0 / КТ-1 / КТ-2 сохранён из WBS</div></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Наименование / проект</th><th>Дата</th><th>Состояние</th><th>Ответственный</th><th></th></tr></thead><tbody>${milestoneRows(ordered)}</tbody></table></div></section>`}
function calendar(){let current=new Date(),base=new Date(current.getFullYear(),current.getMonth()+state.calendarOffset,1),first=(base.getDay()+6)%7,months=42,start=new Date(base.getFullYear(),base.getMonth(),1-first),today=addDays(0);let days=Array.from({length:months},(_,i)=>{let d=new Date(start),date;d.setDate(start.getDate()+i);date=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');return {d,date,matches:db.milestones.filter(m=>m.date===date)}});
return header('Календарь портфеля','Единая шкала контрольных точек по всем проектам СЦ-2.','КАЛЕНДАРЬ',button('К текущему месяцу','calendar-today','','refresh'))+`<section class="panel"><div class="calendar-wrap"><div class="calendar-controls"><div class="calendar-month">${base.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</div><div class="heading-buttons">${button('←','calendar-prev','mini')}${button('→','calendar-next','mini')}</div></div><div class="calendar-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<div class="weekday">${d}</div>`).join('')}${days.map(({d,date,matches})=>`<div class="calendar-day ${d.getMonth()!==base.getMonth()?'faded':''} ${date===today?'today':''}"><span class="calendar-number">${d.getDate()}</span>${matches.map(m=>`<button class="cal-item ${m.state==='accepted'?'green':active(m)&&daydiff(m.date)<0?'red':''}" title="${h(m.name)}" data-milestone="${h(m.id)}">${h(project(m.projectId)?.short)} · ${h(m.name)}</button>`).join('')}</div>`).join('')}</div><div class="legend"><span class="red"><i></i>Просрочено</span><span><i></i>В работе / на приёмке</span><span class="green"><i></i>Принято</span></div></div></section>`}
function initiatives(){return header('Проектные инициативы','Статусы и согласование по маршруту, предусмотренному регламентом.','ИНИЦИИРОВАНИЕ',button('Создать инициативу','new-initiative','primary','plus'))+`<div class="banner">${icon('file')} Маршрут ниже — функциональный прототип. Фактические согласования и уведомления появятся после подключения серверной части.</div><section class="panel"><div class="panel-header"><div class="panel-title">Реестр инициатив на рассмотрении</div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Инициатива</th><th>Инициатор</th><th>Дата</th><th>Этап</th><th></th></tr></thead><tbody>${db.initiatives.map(p=>`<tr><td class="titlecell"><button class="text-link" data-initiative="${h(p.id)}">${h(p.name)}</button><small>${h(p.id)}</small></td><td>${h(p.author)}</td><td>${fmt(p.date)}</td><td>${badge(p.stage<=1?'neutral':p.stage<=3?'yellow':'blue',p.state)}</td><td><button class="button mini" data-initiative="${h(p.id)}">Маршрут</button></td></tr>`).join('')}</tbody></table></div></section>`}
function reportBody(){let c={green:0,yellow:0,red:0};db.projects.forEach(p=>c[health(p)]++);const approved=db.projects.reduce((a,p)=>a+p.approved,0),spent=db.projects.reduce((a,p)=>a+p.spent,0),issues=db.milestones.filter(m=>active(m)&&daydiff(m.date)<0);return `<div class="report-paper"><div class="eyebrow"><span class="red-dot"></span> МОСКОВСКИЙ ПОЛИТЕХ · ДЕМОНСТРАЦИЯ</div><h2>Сводный отчёт по портфелю СЦ-2</h2><p class="subheading">Дата формирования: ${new Date().toLocaleDateString('ru-RU')} · Период: текущий срез · Не содержит реальных данных</p><div class="report-kpi"><div>Проектов<b>${db.projects.length}</b></div><div>В графике<b>${c.green}</b></div><div>Требуют внимания<b>${c.yellow+c.red}</b></div><div>Освоено<b>${money(spent)}</b></div></div><h3>Состояние проектов</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Проект</th><th>Руководитель</th><th>Статус</th><th>Прогресс</th></tr></thead><tbody>${db.projects.map(p=>`<tr><td>${h(p.short)}</td><td>${h(p.manager)}</td><td>${badge(health(p))}</td><td>${p.progress}%</td></tr>`).join('')}</tbody></table></div><h3>Контрольные точки с отклонениями</h3>${issues.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Контрольная точка</th><th>Проект</th><th>Просрочка</th></tr></thead><tbody>${issues.map(m=>`<tr><td>${h(m.name)}</td><td>${h(project(m.projectId)?.short)}</td><td>${-daydiff(m.date)} дн.</td></tr>`).join('')}</tbody></table></div>`:'<p class="content-text">Просроченных контрольных точек нет.</p>'}<h3>Финансовая сводка</h3><p class="content-text">Утверждённый бюджет: <b>${money(approved)}</b>; законтрактовано: <b>${money(db.projects.reduce((s,p)=>s+p.contracted,0))}</b>; потрачено: <b>${money(spent)}</b>; остаток: <b>${money(approved-spent)}</b>.</p><div style="height:3px;background:#bc2736;margin-top:28px"></div><p class="small-help">Сформировано автоматически в демонстрационном приложении. Отчёт не является официальным документом Московского Политеха.</p></div>`}
function reports(){return header('Отчётность','Формирование управленческой аналитики напрямую из структурированных данных проектов.','АНАЛИТИКА',button('Месячный отчёт РП','monthly-report','primary','plus'))+`<div class="panel"><div class="report-controls"><div class="heading-buttons">${button('Экспорт CSV','export-csv','','download')}${button('Сохранить в PDF / печать','print-report','','file')}${button('Обновить','refresh-view','','refresh')}</div></div>${reportBody()}</div><section class="panel" style="margin-top:20px"><div class="panel-header"><div><div class="panel-title">Месячные отчёты руководителей проектов</div><div class="panel-subtitle">Сохранённые отчётные формы (демонстрационный браузер)</div></div></div>${db.reports.length?`<div class="section-pad">${db.reports.slice(0,8).map(r=>`<div class="activity-box"><div class="title-row"><strong>${h(project(r.projectId)?.short)}</strong><small>${fmt(r.date)}</small></div><p><b>Сделано:</b> ${h(r.done)}</p><p><b>Далее:</b> ${h(r.next)}</p><p><b>Риски и комментарии:</b> ${h(r.issues)}</p>${r.decision?`<p><b>Требуется решение:</b> ${h(r.decision)}</p>`:''}</div>`).join('')}</div>`:'<div class="empty">Отчётов ещё нет. Нажмите «Месячный отчёт РП».</div>'}</section>`}
function activity(){return header('Лента событий','Хронология запросов, ответов, управленческих решений и действий по проектам.','КОММУНИКАЦИИ',button('Написать сообщение','new-comment','primary','plus'))+`<div class="two-col"><section class="panel"><div class="panel-header"><div><div class="panel-title">Все события</div><div class="panel-subtitle">История проекта сохраняется для последующей отчётности</div></div></div><div class="section-pad">${db.activity.map(e=>`<div class="activity-box"><div class="title-row"><strong>${h(e.name)}</strong><small>${fmt(e.date)}</small></div><p>${h(e.text)}</p><small><button class="text-link" data-project="${h(e.projectId)}">${h(project(e.projectId)?.short||'Портфель')}</button></small></div>`).join('')}</div></section><section class="panel" style="align-self:start"><div class="panel-header"><div class="panel-title">Новая запись</div></div><form class="section-pad" data-form="comment"><div class="form-grid"><div class="form-field wide"><label>Проект</label><select name="projectId" class="form-control">${db.projects.map(p=>`<option value="${h(p.id)}">${h(p.short)}</option>`).join('')}</select></div><div class="form-field wide"><label>Сообщение / запрос / решение</label><textarea class="form-control" name="text" required placeholder="Например: @РП прошу уточнить статус контрольной точки..."></textarea></div><div class="form-field wide"><button class="button primary" type="submit">${icon('message-square-text')} Разместить в ленте</button></div></div><p class="small-help">В демоверсии @упоминания сохраняются как текст. Адресные уведомления появятся после подключения пользователей и сервера.</p></form></section></div>`}
function settings(){return header('Настройки прототипа','Запланированная инфраструктура, автоматические пороги и демонстрационные функции.','АДМИНИСТРИРОВАНИЕ',button('Сбросить демоданные','reset-demo','danger','refresh'))+`<div class="two-col"><section class="panel section-pad"><div class="panel-title" style="margin-bottom:16px">Контроль исполнения</div><div class="settings-list"><div class="setting-line"><div><strong>Красный статус проекта</strong><small>Просрочка контрольной точки более 14 дней</small></div><span class="setting-value">14 дней</span></div><div class="setting-line"><div><strong>Жёлтый статус проекта</strong><small>Просрочка до 14 дней / приближение КТ за 7 дней</small></div><span class="setting-value">7–14 дней</span></div><div class="setting-line"><div><strong>Обновление РП</strong><small>Отчёт раз в календарный месяц</small></div><span class="setting-value">Ежемесячно</span></div><div class="setting-line"><div><strong>Приёмка КТ</strong><small>Руководитель портфеля СЦ-2</small></div><span class="setting-value">Руководитель портфеля</span></div></div></section><section class="panel section-pad"><div class="panel-title" style="margin-bottom:16px">Архитектура безопасности</div><div class="settings-list"><div class="setting-line"><div><strong>Текущий режим</strong><small>Публичная демоверсия, вымышленные данные</small></div><span class="pill yellow">Прототип</span></div><div class="setting-line"><div><strong>Авторизация</strong><small>Запланированная серверная проверка логина и пароля</small></div><span class="pill neutral">Не подключена</span></div><div class="setting-line"><div><strong>База данных</strong><small>PostgreSQL на защищённом сервере университета</small></div><span class="pill neutral">Не подключена</span></div><div class="setting-line"><div><strong>Email-уведомления</strong><small>Корпоративный SMTP / очередь задач</small></div><span class="pill neutral">Не подключены</span></div><div class="setting-line"><div><strong>Локальные изменения в прототипе</strong><small>Данные хранятся только в браузере</small></div><span class="pill blue">localStorage</span></div></div></section></div>`}
const views={overview,projects,tasks,milestones,calendar,initiatives,reports,activity,settings};
function selectedProjectModal(p){const tab=state.projectTab;const tabs=[['summary','Обзор'],['milestones','Контрольные точки'],['tasks','Задачи'],['kpi','KPI и финансы'],['activity','Обсуждение']];let body='';if(tab==='summary'){body=`<p class="content-text">${h(p.description||'Описание отсутствует')}</p><div class="metrics-row" style="margin:20px 0"><div class="metrics-box"><span>Здоровье</span><div style="margin-top:12px">${badge(health(p))}</div></div><div class="metrics-box"><span>Готовность</span><b>${p.progress}%</b></div><div class="metrics-box"><span>Контрольные точки</span><b>${pm(p.id).length}</b></div><div class="metrics-box"><span>Бюджет</span><b>${money(p.approved)}</b></div></div><div class="two-col"><div><div class="label-line"><span>Руководитель проекта</span><b>${h(p.manager)}</b></div><div class="label-line"><span>Тип</span><b>${h(p.type)}</b></div><div class="label-line"><span>Цикл</span><b>${h(p.cycle)}</b></div><div class="label-line"><span>Фаза</span><b>${h(p.phase)}</b></div><div class="label-line"><span>Последнее обновление</span><b>${fmt(p.updated)}</b></div></div><div><span class="smallcaps">Стратегическая инициатива</span><p class="content-text">${h(p.initiative)}</p><span class="smallcaps">Текущий сигнал</span><p class="content-text">${h(reason(p))}</p></div></div>`}
else if(tab==='milestones'){body=`<div class="table-scroll"><table class="data-table"><thead><tr><th>КТ</th><th>Срок</th><th>Статус</th><th></th></tr></thead><tbody>${pm(p.id).map(m=>`<tr><td><div class="titlecell">${h(m.name)}<small>${h(m.id)} · уровень ${m.level}</small></div></td><td>${fmt(m.date)}</td><td>${badge(m.state==='accepted'?'green':m.state==='submitted'?'blue':daydiff(m.date)<0?'red':'neutral',m.state==='accepted'?'Принята':m.state==='submitted'?'На приёмке':daydiff(m.date)<0?'Просрочена':'В работе')}</td><td><button class="button mini" data-milestone="${h(m.id)}">Открыть</button></td></tr>`).join('')}</tbody></table></div>`}
else if(tab==='tasks'){body=`<div class="table-scroll"><table class="data-table"><thead><tr><th>Задача</th><th>Ответственный</th><th>Срок</th><th>Статус</th></tr></thead><tbody>${pt(p.id).map(t=>`<tr><td>${h(t.name)}</td><td>${h(t.assignee)}</td><td>${fmt(t.due)}</td><td>${badge(t.status==='Выполнена'?'green':daydiff(t.due)<0?'red':'neutral',t.status)}</td></tr>`).join('')||'<tr><td colspan="4">Задач нет</td></tr>'}</tbody></table></div>`}
else if(tab==='kpi'){body=`<div class="metrics-row" style="margin-bottom:23px"><div class="metrics-box"><span>Утверждено</span><b>${money(p.approved)}</b></div><div class="metrics-box"><span>Законтрактовано</span><b>${money(p.contracted)}</b></div><div class="metrics-box"><span>Потрачено</span><b>${money(p.spent)}</b></div><div class="metrics-box"><span>Остаток</span><b>${money(p.approved-p.spent)}</b></div></div><div class="budget-bar"><span class="spent" style="width:${Math.min(100,p.approved?p.spent/p.approved*100:0)}%"></span><span style="width:${Math.max(0,Math.min(100,p.approved?(p.contracted-p.spent)/p.approved*100:0))}%"></span></div><p class="small-help">Красным — освоено, розовым — законтрактовано сверх освоенного</p><h3 style="font-size:14px;margin-top:27px">Вклад в KPI</h3>${p.kpi?.map(k=>`<div class="kpi-item"><strong>${h(k.code)} · ${h(k.label)}</strong><span class="content-text">База: <b>${h(k.base)}</b> · Цель: <b>${h(k.target)}</b> · Факт: <b>${h(k.fact)}</b></span></div>`).join('')||'<div class="empty">KPI не привязаны</div>'}<h3 style="font-size:14px;margin-top:23px">Риски</h3>${p.risks?.map(r=>`<div class="notice"><span class="notice-dot yellow">${icon('alert')}</span><div><b>${h(r.name)}</b><small>Уровень: ${h(r.level)}</small></div></div>`).join('')||'<p class="content-text">Критические риски не зарегистрированы.</p>'}`}
else if(tab==='activity'){body=`<div>${db.activity.filter(e=>e.projectId===p.id).map(e=>`<div class="activity-box"><strong>${h(e.name)}</strong><p>${h(e.text)}</p><small>${fmt(e.date)}</small></div>`).join('')||'<div class="empty">Сообщений ещё нет</div>'}</div><form data-form="project-comment" data-projectid="${h(p.id)}"><div class="notes-input"><textarea name="text" class="form-control" required placeholder="Комментарий, запрос, @упоминание, решение..."></textarea><button type="submit" class="button primary">Отправить</button></div></form>`}
return `<div class="modal wide"><div class="modal-head"><div class="project-hero"><div class="project-badge">СЦ</div><div><div class="id-tag">${h(p.id)} · ${h(p.phase)}</div><h2>${h(p.name)}</h2></div></div><button class="close" data-action="close-modal" aria-label="Закрыть">${icon('x')}</button></div><div class="card-tabs">${tabs.map(([id,label])=>`<button data-tab="${id}" class="${id===tab?'selected':''}">${label}</button>`).join('')}</div><div class="modal-body">${body}</div><div class="modal-actions">${button('Месячный отчёт','monthly-report','','file')}${button('Закрыть','close-modal','primary')}</div></div>`}
function milestoneModal(m){const p=project(m.projectId),due=daydiff(m.date);return `<div class="modal"><div class="modal-head"><div><div class="id-tag">${h(m.id)} · уровень ${m.level}</div><h2>${h(m.name)}</h2></div><button class="close" data-action="close-modal">${icon('x')}</button></div><div class="modal-body"><div class="form-grid"><div class="form-field"><label>Проект</label><div class="content-text">${h(p?.short)}</div></div><div class="form-field"><label>Ответственный</label><div class="content-text">${h(m.owner)}</div></div><div class="form-field"><label>Плановый срок</label><div class="content-text">${fmt(m.date)}</div></div><div class="form-field"><label>Состояние</label>${badge(m.state==='accepted'?'green':m.state==='submitted'?'blue':due<0?'red':'neutral',m.state==='accepted'?'Принята':m.state==='submitted'?'На приёмке':due<0?'Просрочена':'В работе')}</div><div class="form-field wide"><label>Подтверждение / документ</label><p class="content-text">${h(m.evidence||'Пока отсутствует')}</p></div></div>${m.state!=='accepted'?`<form id="evidenceForm" data-form="evidence" data-milestoneid="${h(m.id)}"><div class="form-field"><label>Комментарий и ссылка на подтверждение (демо, без загрузки файла)</label><textarea class="form-control" name="evidence" placeholder="Что выполнено, где размещён подтверждающий результат?">${h(m.evidence)}</textarea></div><div class="heading-buttons" style="margin-top:15px"><button type="submit" class="button">Передать на приёмку</button>${m.state==='submitted'?`<button type="button" class="button primary" data-accept="${h(m.id)}">Принять контрольную точку</button><button type="button" class="button danger" data-return="${h(m.id)}">Вернуть на доработку</button>`:''}</div></form>`:`<div class="banner">${icon('check')} Результат принят руководителем портфеля.</div>`}<p class="small-help">В пилоте приёмку проводит руководитель портфеля. Авторизация пока не подключена.</p></div></div>`}
function initiativeModal(x){return `<div class="modal"><div class="modal-head"><div><div class="id-tag">${h(x.id)}</div><h2>${h(x.name)}</h2></div><button class="close" data-action="close-modal">${icon('x')}</button></div><div class="modal-body"><div class="label-line"><span>Инициатор</span><b>${h(x.author)}</b></div><div class="label-line"><span>Дата подачи</span><b>${fmt(x.date)}</b></div><p class="content-text">${h(x.description)}</p><h3 style="font-size:13px;margin-top:21px">Маршрут согласования</h3><div class="stepper">${stages.map((s,i)=>`<div class="step ${i<x.stage?'done':''} ${i===x.stage?'current':''}"><span class="number">${i<x.stage?'✓':i+1}</span><span>${h(s)}</span></div>`).join('')}</div><div class="banner">${icon('git-pull-request')} Текущий этап: <strong>${h(x.state)}</strong>. В рабочей версии будут отображаться согласующие, сроки и решения.</div><p class="content-text">Последовательность согласования по ролям включает инициатора, руководителя проекта, ведущего заказчика, проректора, профильную дирекцию, ЦПО, владельца СЦ и программный комитет. Перечень и порядок требуют финального согласования для пилота.</p></div><div class="modal-actions">${button('Следующий этап','initiative-next','primary','arrow')}${button('Закрыть','close-modal')}</div></div>`}
function formModal(kind){const ps=db.projects.map(p=>`<option value="${h(p.id)}">${h(p.short)}</option>`).join('');const shortFields={
 'new-project':{title:'Создание проекта',desc:'Демонстрационная карточка. Проверка регламента и согласование будут подключены позже.',form:'project',fields:`<div class="form-field wide"><label>Название проекта *</label><input name="name" required class="form-control" placeholder="Например, создание лаборатории цифрового производства"/></div><div class="form-field"><label>Руководитель *</label><input name="manager" required class="form-control" placeholder="ФИО"/></div><div class="form-field"><label>Тип проекта</label><select name="type" class="form-control"><option>Стратегический</option><option>Операционный</option></select></div><div class="form-field"><label>Цикл</label><select name="cycle" class="form-control"><option>Новый</option><option>Продолжающийся</option><option>Перезапускающийся</option></select></div><div class="form-field"><label>Плановый бюджет, ₽</label><input name="approved" type="number" min="0" value="0" class="form-control"/></div><div class="form-field wide"><label>Краткое описание</label><textarea name="description" class="form-control"></textarea></div>`},
 'new-task':{title:'Новая задача',desc:'Доступна для создания любому участнику. Серверную проверку ролей добавим позже.',form:'task',fields:`<div class="form-field wide"><label>Проект *</label><select name="projectId" class="form-control">${ps}</select></div><div class="form-field wide"><label>Задача *</label><input name="name" required class="form-control" placeholder="Что нужно сделать?"/></div><div class="form-field"><label>Ответственный *</label><input name="assignee" required class="form-control" placeholder="ФИО"/></div><div class="form-field"><label>Срок *</label><input name="due" type="date" value="${addDays(7)}" required class="form-control"/></div><div class="form-field"><label>Приоритет</label><select name="priority" class="form-control"><option>Средний</option><option>Высокий</option><option>Низкий</option></select></div><div class="form-field"><label>Рабочее состояние</label><select name="status" class="form-control">${statuses.map(s=>`<option>${h(s)}</option>`).join('')}</select></div>`},
 'new-milestone':{title:'Новая контрольная точка',desc:'Контрольные точки существуют отдельно от задач и требуют подтверждения результата.',form:'milestone',fields:`<div class="form-field wide"><label>Проект *</label><select name="projectId" class="form-control">${ps}</select></div><div class="form-field wide"><label>Проверяемый результат *</label><input name="name" required class="form-control" placeholder="Например, утверждён протокол экспертизы"/></div><div class="form-field"><label>Плановая дата *</label><input name="date" type="date" value="${addDays(21)}" required class="form-control"/></div><div class="form-field"><label>Уровень WBS</label><select name="level" class="form-control"><option>0</option><option>1</option><option>2</option></select></div>`},
 'new-initiative':{title:'Новая инициатива',desc:'Черновик заявки. Расширенный паспорт проекта появится в следующей версии.',form:'initiative',fields:`<div class="form-field wide"><label>Название инициативы *</label><input name="name" required class="form-control"/></div><div class="form-field"><label>Инициатор *</label><input name="author" required class="form-control"/></div><div class="form-field"><label>Ведущая стратегическая цель</label><input class="form-control" value="СЦ-2" readonly/></div><div class="form-field wide"><label>Проблема / ожидаемый результат</label><textarea name="description" class="form-control"></textarea></div>`},
 'monthly-report':{title:'Месячный отчёт руководителя проекта',desc:'Краткая форма; данные о ходе проекта и контрольных точках собираются автоматически.',form:'monthly',fields:`<div class="form-field wide"><label>Проект *</label><select name="projectId" class="form-control">${ps}</select></div><div class="form-field wide"><label>Что выполнено за месяц *</label><textarea name="done" required class="form-control" placeholder="Ключевые результаты за отчётный период"></textarea></div><div class="form-field wide"><label>Что запланировано на следующий месяц *</label><textarea name="next" required class="form-control"></textarea></div><div class="form-field wide"><label>Риски / отклонения / комментарий к автоматическому статусу *</label><textarea name="issues" required class="form-control"></textarea></div><div class="form-field wide"><label>Требуется управленческое решение?</label><textarea name="decision" class="form-control" placeholder="Укажите, кто должен принять решение и по какому вопросу"></textarea></div>`},
 'new-comment':{title:'Новое сообщение',desc:'Фиксация запросов, ответов и решений по проекту.',form:'comment',fields:`<div class="form-field wide"><label>Проект *</label><select name="projectId" class="form-control">${ps}</select></div><div class="form-field wide"><label>Сообщение *</label><textarea name="text" required class="form-control"></textarea></div>`}
};const f=shortFields[kind];if(!f)return'';return `<div class="modal"><div class="modal-head"><div><h2>${f.title}</h2><p class="subheading" style="margin-bottom:0">${f.desc}</p></div><button class="close" data-action="close-modal">${icon('x')}</button></div><form data-form="${f.form}"><div class="modal-body"><div class="form-grid">${f.fields}</div></div><div class="modal-actions"><button class="button" type="button" data-action="close-modal">Отмена</button><button class="button primary" type="submit">${icon('check')} Сохранить</button></div></form></div>`}
function renderModal(){if(state.modal==='project'&&state.selectedProject)return `<div class="modal-backdrop" data-backdrop="1">${selectedProjectModal(project(state.selectedProject))}</div>`;
if(state.modal==='milestone')return `<div class="modal-backdrop" data-backdrop="1">${milestoneModal(db.milestones.find(m=>m.id===state.selectedMilestone))}</div>`;
if(state.modal==='initiative')return `<div class="modal-backdrop" data-backdrop="1">${initiativeModal(db.initiatives.find(x=>x.id===state.selectedInitiative))}</div>`;
return `<div class="modal-backdrop" data-backdrop="1">${formModal(state.modal)}</div>`}
function render(){document.getElementById('app').innerHTML=frame();document.title=`${nav.find(n=>n[0]===state.view)?.[2]||'МП Проекты'} · МП Проекты`}
function openProject(id,tab='summary'){state.selectedProject=id;state.projectTab=tab;state.modal='project';render()}
function downloadCsv(){const rows=[['Код','Проект','Руководитель','Тип','Статус','Готовность, %','Утверждено, руб','Законтрактовано, руб','Потрачено, руб'],...db.projects.map(p=>[p.id,p.name,p.manager,p.type,labelHealth[health(p)],p.progress,p.approved,p.contracted,p.spent])];const text='\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\r\n');const file=new Blob([text],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download='mp-projects-portfolio-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const actionMap={
'close-modal':()=>{state.modal=null;render()},'mobilemenu':()=>{state.mobileMenu=!state.mobileMenu;render()},'notifications':()=>{state.showNotifications=!state.showNotifications;render()},
'new-project':()=>{state.modal='new-project';render()},'new-task':()=>{state.modal='new-task';render()},'new-milestone':()=>{state.modal='new-milestone';render()},'new-initiative':()=>{state.modal='new-initiative';render()},'new-comment':()=>{state.modal='new-comment';render()},'monthly-report':()=>{state.modal='monthly-report';render()},
'go-reports':()=>navTo('reports'),'clear-filters':()=>{state.filter='all';state.type='all';state.search='';render()},
'calendar-prev':()=>{state.calendarOffset--;render()},'calendar-next':()=>{state.calendarOffset++;render()},'calendar-today':()=>{state.calendarOffset=0;render()},
'print-report':()=>window.print(),'export-csv':downloadCsv,'refresh-view':()=>render(),
'reset-demo':()=>{if(confirm('Сбросить все локальные изменения и восстановить демонстрационные данные?')){db=structuredClone(seed);save();navTo('overview');notify('Демонстрационные данные восстановлены')}}
};
document.addEventListener('click',e=>{
 const target=e.target.closest('[data-action],[data-nav],[data-project],[data-milestone],[data-initiative],[data-tab],[data-accept],[data-return],[data-backdrop]');if(!target)return;
 if(target.dataset.backdrop){if(e.target===target){state.modal=null;render()}return}
 if(target.dataset.action){actionMap[target.dataset.action]?.();return}
 if(target.dataset.nav){navTo(target.dataset.nav);return}
 if(target.dataset.project){openProject(target.dataset.project);return}
 if(target.dataset.milestone){state.selectedMilestone=target.dataset.milestone;state.modal='milestone';render();return}
 if(target.dataset.initiative){state.selectedInitiative=target.dataset.initiative;state.modal='initiative';render();return}
 if(target.dataset.tab){state.projectTab=target.dataset.tab;render();return}
 if(target.dataset.accept){const m=db.milestones.find(m=>m.id===target.dataset.accept);if(m){m.state='accepted';addActivity(m.projectId,'Руководитель портфеля',`Принята контрольная точка ${m.id}: ${m.name}`,'milestone');state.modal=null;notify('Контрольная точка принята')}return}
 if(target.dataset.return){const m=db.milestones.find(m=>m.id===target.dataset.return);const reason=prompt('Причина возврата на доработку (обязательна):');if(m&&reason?.trim()){m.state='active';addActivity(m.projectId,'Руководитель портфеля',`Контрольная точка ${m.id} возвращена на доработку: ${reason.trim()}`,'alert');state.modal=null;notify('Контрольная точка возвращена на доработку')}return}
});
document.addEventListener('input',e=>{if(e.target.id==='projectsSearch'){let pos=e.target.selectionStart;state.search=e.target.value;render();const inp=document.getElementById('projectsSearch');if(inp){inp.focus();inp.setSelectionRange(pos,pos)}}});
document.addEventListener('change',e=>{
if(e.target.id==='demoRole'){state.role=e.target.value;state.showNotifications=false;render();return}
if(e.target.id==='projectsStatus'){state.filter=e.target.value;render();return}
if(e.target.id==='projectsType'){state.type=e.target.value;render();return}
if(e.target.id==='tasksProject'){state.reportProject=e.target.value;render();return}
if(e.target.dataset.taskstatus){const t=db.tasks.find(t=>t.id===e.target.dataset.taskstatus);if(t){t.status=e.target.value;addActivity(t.projectId,'Участник проекта',`Задача «${t.name}»: статус изменён на «${t.status}».`);notify('Статус задачи обновлён')}return}
});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag]');if(card&&e.dataTransfer){e.dataTransfer.setData('text/plain',card.dataset.drag);e.dataTransfer.effectAllowed='move'}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-dropstatus]')){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move'}});
document.addEventListener('drop',e=>{let col=e.target.closest('[data-dropstatus]');if(!col)return;e.preventDefault();let id=e.dataTransfer?.getData('text/plain'),t=db.tasks.find(t=>t.id===id);if(t&&statuses.includes(col.dataset.dropstatus)){t.status=col.dataset.dropstatus;addActivity(t.projectId,'Участник проекта',`Задача «${t.name}»: изменён статус на «${t.status}».`);notify('Задача перемещена')}});
document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form,values=Object.fromEntries(new FormData(form).entries());
if(type==='project'){
 const num=String(Math.max(0,...db.projects.map(p=>Number(p.id.split('-').at(-1))||0))+1).padStart(3,'0');let id='СЦ-2-'+num;
 db.projects.push({id,name:values.name.trim(),short:values.name.trim().slice(0,48),manager:values.manager.trim(),unit:'Не указано',type:values.type,cycle:values.cycle,phase:'Инициация',initiative:'Не указана',progress:0,approved:Number(values.approved)||0,contracted:0,spent:0,kpi:[],updated:addDays(0),risks:[],description:values.description||'Новый демонстрационный проект'});
 addActivity(id,'Пользователь демоверсии',`Создана карточка проекта ${id}.`);state.modal=null;notify('Проект добавлен в реестр');return;
}
if(type==='task'){
 const id='З-'+Date.now().toString().slice(-6);db.tasks.push({id,projectId:values.projectId,milestoneId:null,name:values.name.trim(),assignee:values.assignee.trim(),due:values.due,status:values.status,priority:values.priority});addActivity(values.projectId,'Участник проекта',`Создана задача «${values.name.trim()}».`);state.modal=null;navTo('tasks');notify('Задача создана');return;
}
if(type==='milestone'){
 const id='КТ-'+Date.now().toString().slice(-6),p=project(values.projectId);db.milestones.push({id,projectId:values.projectId,name:values.name.trim(),level:Number(values.level),date:values.date,owner:p?.manager||'',state:'active',evidence:''});addActivity(values.projectId,'Руководитель проекта',`Добавлена контрольная точка ${id}.`);state.modal=null;navTo('milestones');notify('Контрольная точка добавлена');return;
}
if(type==='initiative'){
 const id='ИН-2027-'+String(db.initiatives.length+1).padStart(2,'0');db.initiatives.unshift({id,name:values.name.trim(),author:values.author.trim(),date:addDays(0),state:'Черновик',stage:0,description:values.description||''});save();state.modal=null;navTo('initiatives');notify('Черновик инициативы создан');return;
}
if(type==='monthly'){
 const p=project(values.projectId);p.updated=addDays(0);db.reports.unshift({id:Date.now(),projectId:p.id,date:addDays(0),...values,health:health(p)});addActivity(p.id,p.manager,`Сохранён месячный отчёт: ${values.done.trim().slice(0,150)}`,'comment');state.modal=null;notify('Месячный отчёт сохранён в браузере');return;
}
if(type==='comment'||type==='project-comment'){
 const pid=values.projectId||form.dataset.projectid;addActivity(pid,state.role==='portfolio'?'Руководитель портфеля':'Участник проекта',values.text.trim(),'comment');if(state.modal==='project'){state.projectTab='activity'}else{state.modal=null}notify('Сообщение добавлено');return;
}
if(type==='evidence'){
 const m=db.milestones.find(m=>m.id===form.dataset.milestoneid);if(m){m.evidence=values.evidence?.trim()||'';if(!m.evidence){notify('Укажите подтверждение выполнения',true);return}m.state='submitted';addActivity(m.projectId,m.owner,`Контрольная точка ${m.id} передана на приёмку.`,'milestone');state.modal=null;notify('Контрольная точка отправлена на приёмку')}return;
}
});
// Initiative step demo (dispatch from button click; no server workflow yet)
actionMap['initiative-next']=()=>{const x=db.initiatives.find(q=>q.id===state.selectedInitiative);if(x){if(x.stage<stages.length-1){x.stage++;x.state=stages[x.stage];save();notify('Демонстрационный этап согласования обновлён')}else{notify('Достигнут последний этап маршрута')}}};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render()}});
render();
